'use strict';
const $=s=>document.querySelector(s);
const lessons=[
{id:'setup',level:0,title:'Trust the setup first',time:3,desc:'Check whether a trace can answer your question.',observe:'Two traces look different, but one used a much longer pulse.',interpret:'A changed setup can change what the instrument resolves. The difference alone does not establish fiber degradation.',verify:'Compare fiber ID, direction, wavelength, pulse, range, averaging, refractive index and launch/receive arrangements.',act:'Resolve setup differences using the approved test procedure before comparing events.',q:'The second trace hides two nearby events. What do you check first?',answers:['Pulse width and measurement conditions','Whether the fiber suddenly became shorter','Whether the hidden splice has passed'],correct:0,why:'A longer pulse can merge nearby events. First establish that the measurements are comparable.'},
{id:'events',level:0,title:'Read the shape of an event',time:4,desc:'Connect peaks, steps and slopes to useful evidence.',observe:'A narrow peak rises above the backscatter, followed by a step down.',interpret:'The peak indicates reflection. The step indicates loss. These are different measurements.',verify:'Check event location, dead zones and the event table. A reflective event can have several causes.',act:'Use the approved inspection or confirmation process. Shape alone cannot prove contamination.',q:'A tall reflective peak proves which conclusion?',answers:['The connector is contaminated','A reflective event is present; the cause needs confirmation','The link must pass because light returned'],correct:1,why:'Reflection is observable. Contamination is a hypothesis that needs inspection and corroboration.'},
{id:'handling',level:0,title:'Protect the fiber and the result',time:3,desc:'Link handling, cleanliness and test readiness.',observe:'A result changes after reconnecting a test lead.',interpret:'The test interface can contribute to the change. Avoid blaming the installed fiber immediately.',verify:'Confirm lead identity and condition; follow the authorized connector inspection and cleaning sequence and optical safety requirements.',act:'Retest with the approved setup and retain the original result. Never look into a fiber or connector.',q:'What is the most useful next step after an unexplained reconnect change?',answers:['Delete the first trace','Increase the pass limit','Check the test interface using the authorized procedure'],correct:2,why:'Preserve evidence and verify the test interface before assigning a cause to the installed link.'},
{id:'wavelength',level:1,title:'Compare wavelengths',time:4,desc:'Explore why a bend can stand out at 1550 nm.',observe:'An aligned event has more loss at 1550 nm than at 1310 nm in a synthetic single-mode example.',interpret:'A wavelength-sensitive loss can support a bending hypothesis. It is not a unique diagnosis.',verify:'Check equivalent settings, fiber type, event alignment and the physical route when authorized.',act:'Confirm with the approved procedure before changing the installation.',q:'Loss increases at the same location at the longer wavelength. What can you conclude?',answers:['Bending is a candidate cause to investigate','A break will occur tomorrow','Every splice has failed'],correct:0,why:'Wavelength dependence is useful evidence for a bend hypothesis, but other causes and measurement conditions still matter.'},
{id:'pulse',level:1,title:'Pulse width versus detail',time:3,desc:'Trade event separation against measurement reach.',observe:'With a wider pulse, two close reflections blend together in the lab.',interpret:'Longer pulses generally improve reach but enlarge dead zones. Closely spaced events can become difficult to separate.',verify:'Choose settings appropriate to the link and the approved test method; assess both event and attenuation dead zones.',act:'If permitted, repeat with a shorter pulse to investigate close events. Do not assume a missing event is absent.',q:'Which change generally helps separate closely spaced events?',answers:['A longer pulse in every situation','A shorter pulse, if sufficient signal remains','Changing the asset label'],correct:1,why:'Short pulses can improve spatial separation, with a tradeoff in reach. This lab demonstrates the relationship, not instrument specifications.'},
{id:'direction',level:1,title:'Understand an apparent gainer',time:4,desc:'Use both directions to interpret splice loss.',observe:'The same splice reads −0.20 dB from A→B and +0.50 dB from B→A.',interpret:'Backscatter differences can produce an apparent gain in one direction. The fiber does not amplify the light.',verify:'Match the same physical event in both directions, with comparable conditions and valid measurements.',act:'Where required by the governing method, average directional event losses: (−0.20 + 0.50) / 2 = 0.15 dB. Apply only approved acceptance limits.',q:'What is the bidirectional average in this example?',answers:['0.70 dB','−0.35 dB','0.15 dB'],correct:2,why:'Use the signed loss values from the same event: (−0.20 + 0.50) / 2 = 0.15 dB. This is not an AT&T acceptance threshold.'},
{id:'trend',level:2,title:'A change is not a forecast',time:5,desc:'Separate a rising loss from a validated failure warning.',observe:'Repeated comparable traces show a persistent increase at one event.',interpret:'This supports a degradation investigation. Predicting a failure requires validation against confirmed outcomes.',verify:'Check measurement quality, maintenance history, persistence and whether the prediction method was evaluated on later, independent incidents.',act:'Escalate the evidence through the approved workflow. Report uncertainty and avoid unsupported failure dates.',q:'What turns an anomaly score into a defensible failure prediction?',answers:['A bright red alert','Validation against future confirmed failures and non-failures','A single unusual trace'],correct:1,why:'Prediction needs a defined horizon, independent validation, false-alert measurement and useful warning lead time.'},
{id:'end',level:2,title:'Break, end or poor reach?',time:4,desc:'Resolve uncertainty before declaring a break.',observe:'Backscatter disappears earlier than in the reference trace.',interpret:'A break is possible, but range, noise, high upstream loss and the expected fiber end must be checked.',verify:'Verify asset length, range, dynamic range, end reflection, baseline and the opposite direction when available.',act:'Use the approved confirmation and escalation process. An absent end reflection does not rule out a break.',q:'An early trace ending without a strong reflection means…',answers:['A break is impossible','The fiber always passes','Several explanations remain; verify setup and location'],correct:2,why:'Breaks need not produce a strong reflection. Poor reach or excessive preceding loss can also obscure the rest of the fiber.'},
{id:'mentor',level:2,title:'Explain your next decision',time:3,desc:'Turn expert pattern recognition into a teachable case.',observe:'A junior technician identifies a suspicious event but cannot explain the next test.',interpret:'Naming a defect is less useful than linking evidence, uncertainty and a justified action.',verify:'Ask: what do you see, what else could cause it, what check would distinguish the possibilities, and which procedure applies?',act:'Capture one de-identified case for technical and policy review. Unreviewed experience is not a work instruction.',q:'Which SME note is most useful to a learner?',answers:['“I just know it is bad.”','“Always replace that section.”','“Here is the observation, alternative cause and approved confirmation step.”'],correct:2,why:'A short explanation makes the reasoning transferable and reviewable without substituting experience for procedure.'}
];
let state={level:0,done:[],view:'learn',scenario:'bend',wave:'both',pulse:20,day:0};try{Object.assign(state,JSON.parse(localStorage.getItem('fiber-learning')||'{}'))}catch{}state.view='learn';
function save(){try{localStorage.setItem('fiber-learning',JSON.stringify({level:state.level,done:state.done}))}catch{}}
const notice=()=>'<div class="notice"><b>Practice, not qualification.</b> Synthetic examples. AT&T procedures and acceptance limits are pending authorized review. Follow current approved work instructions.</div>';
const footer=()=>'<footer>General principles: <a href="https://www.exfo.com/en/resources/glossary/optical-time-domain-reflectometer-otdr/" target="_blank" rel="noopener">EXFO OTDR guide</a> · <a href="https://www.flukenetworks.com/expertise/learn-about/otdr" target="_blank" rel="noopener">Fluke Networks OTDR guide</a>. These sources do not establish AT&T policy.</footer>';
function go(view){state.view=view;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));({learn:renderLearn,lab:renderLab,aids:renderAids,design:renderDesign}[view]||renderLearn)();window.scrollTo(0,0)}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));$('.brand').onclick=e=>{e.preventDefault();go('learn')};
function chart(scenario='bend',wave='both',pulse=20,day=0){const X=d=>48+d*142,Y=v=>40+(26-v)*8;function line(w){let a=[];for(let i=0;i<=500;i++){let d=i/100,v=24-d*.5;v-=d>=1.1?.35:0;v+=3.8*Math.exp(-1*((d-1.1)/.025)**2);if(scenario==='bend')v-=d>=2.5?(w===1550?2.4:.5):0;if(scenario==='splice')v-=d>=2.5?1.2:0;if(scenario==='gainer')v+=d>=2.5?(w===1310?.2:-.5):0;if(scenario==='trend')v-=d>=2.5?.4+(w===1550?day*.22:0):0;if(scenario==='pulse'){let width=.018+pulse/850;v+=4*Math.exp(-1*((d-2.4)/width)**2)+3.5*Math.exp(-1*((d-2.58)/width)**2);v-=d>=2.62?.6:0}if(scenario==='end'&&d>=3.5)v=3+Math.sin(i*1.8)*.6;else if(d>=4.7)v=3+Math.sin(i*1.8)*.6;else v+=5*Math.exp(-1*((d-4.67)/.022)**2);a.push(`${X(d).toFixed(1)},${Y(v).toFixed(1)}`)}return a.join(' ')}let ticks=[0,1,2,3,4,5].map(d=>`<line x1="${X(d)}" y1="30" x2="${X(d)}" y2="240" stroke="#294650"/><text x="${X(d)}" y="264" text-anchor="middle">${d}</text>`).join('');let ys=[5,15,25].map(v=>`<line x1="48" y1="${Y(v)}" x2="758" y2="${Y(v)}" stroke="#294650"/><text x="35" y="${Y(v)+5}" text-anchor="end">${v}</text>`).join('');return `<svg viewBox="0 0 800 310" role="img" aria-label="Synthetic OTDR trace: ${scenario}. Relative backscatter in dB versus distance in kilometers. A reflective event is at 1.1 km and the comparison event near 2.5 km.">${ticks}${ys}<text x="48" y="19">Relative backscatter · dB</text>${wave!=='1550'?`<polyline points="${line(1310)}" fill="none" stroke="#70d6ff" stroke-width="2.5"/>`:''}${wave!=='1310'?`<polyline points="${line(1550)}" fill="none" stroke="#d6f46b" stroke-width="2.5"/>`:''}<line x1="403" y1="32" x2="403" y2="235" stroke="#d8e8eb" stroke-dasharray="4 5"/><text x="420" y="40">Investigate this event</text><text x="400" y="297" text-anchor="middle">Distance · km</text></svg><div class="legend"><span class="cyan">━ ${scenario==='gainer'?'A → B':scenario==='trend'?'Baseline':'1310 nm'}</span><span class="lime">━ ${scenario==='gainer'?'B → A, aligned':scenario==='trend'?'Follow-up':'1550 nm'}</span><span>Schematic · not to measurement scale</span></div>`}
function renderLearn(){let list=lessons.filter(l=>l.level<=state.level),done=list.filter(l=>state.done.includes(l.id)).length;$('#main').innerHTML=`<div class="topline"><div><div class="eyebrow">LEARN & PRACTICE</div><h1>Build confidence. One trace at a time.</h1><p class="muted">Short practice for the decisions you make in the field.</p></div><label class="level">Choose your path<select id="level"><option value="0">Starting out</option><option value="1">Building experience</option><option value="2">Advanced / mentor</option></select></label></div><div class="feature"><div><div class="eyebrow">HANDS-ON · 4 MINUTES</div><h2>Same fiber.<br>Two wavelengths.<br>What changed?</h2><p>Compare the traces. Spot the relationship. Decide what to verify next.</p><button class="primary" id="openLab">Explore the trace lab ↗</button></div><div class="chart">${chart()}</div></div>${notice()}<div class="section-head"><h2>Your learning path</h2><span class="meta">${done} of ${list.length} practiced · saved on this device</span></div><div class="progressbar"><span style="width:${done/list.length*100}%"></span></div><div class="cards">${list.map((l,i)=>`<article class="card"><div class="number">${String(i+1).padStart(2,'0')} / ${l.time} MIN ${state.done.includes(l.id)?'· PRACTICED':''}</div><h3>${l.title}</h3><p>${l.desc}</p><button class="secondary" data-lesson="${l.id}">${state.done.includes(l.id)?'Practice again':'Start lesson'} →</button></article>`).join('')}</div>${footer()}`;$('#level').value=state.level;$('#level').onchange=e=>{state.level=Number(e.target.value);save();renderLearn()};$('#openLab').onclick=()=>go('lab');document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>renderLesson(b.dataset.lesson))}
function renderLesson(id){const l=lessons.find(l=>l.id===id);$('#main').innerHTML=`<button class="secondary" id="back">← Learning path</button><div class="section-head"><div><div class="eyebrow">${l.time}-MINUTE LESSON</div><h1>${l.title}</h1></div></div>${notice()}<div class="steps">${['observe','interpret','verify','act'].map((s,i)=>`<div><b>${i+1}. ${s[0].toUpperCase()+s.slice(1)}</b><p>${l[s]}</p></div>`).join('')}</div><section class="panel"><span class="eyebrow">CHECK YOUR REASONING</span><h2 style="margin-top:12px">${l.q}</h2><div class="answers">${l.answers.map((a,i)=>`<button class="answer" data-answer="${i}">${a}</button>`).join('')}</div><div id="feedback" aria-live="polite"></div></section><p class="muted">A correct answer records practice only. It does not authorize work or certify competence.</p>${footer()}`;$('#back').onclick=renderLearn;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const ok=Number(b.dataset.answer)===l.correct;document.querySelectorAll('[data-answer]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');$('#feedback').innerHTML=`<div class="feedback ${ok?'':'retry'}"><b>${ok?'That reasoning fits the evidence.':'Take another look.'}</b><p>${ok?l.why:'Return to the observation and verification steps. Choose the answer supported by the available evidence.'}</p>${ok?'<button class="secondary" id="continue">Continue learning →</button>':''}</div>`;if(ok){if(!state.done.includes(id))state.done.push(id);save();$('#continue').onclick=renderLearn}})}
const scenarioInfo={bend:['Wavelength-sensitive loss','At 2.5 km, this example has a 0.5 dB step at 1310 nm and a 2.4 dB step at 1550 nm.','A bend is a candidate explanation. Align events and confirm settings, fiber type and the physical condition through the approved procedure.'],splice:['Non-reflective loss','Both traces show a 1.2 dB step at 2.5 km with no modeled reflection.','A splice or bend can cause non-reflective loss. A single shape does not identify the cause. Verify in both directions and compare wavelengths.'],pulse:['Two nearby reflections','Two modeled events are 180 m apart. Increase the pulse to watch them overlap. Width is exaggerated for teaching.','A wide pulse can hide event detail. Shorter pulses can improve separation if usable signal remains. Actual dead zones depend on the instrument and event.'],gainer:['Directional backscatter mismatch','At the aligned splice: A→B = −0.20 dB, B→A = +0.50 dB; average = 0.15 dB.','An apparent gainer is not amplification. Both traces here are aligned schematic event views; an actual reverse trace also needs distance transformation.'],trend:['Loss increases over time','The follow-up event increases while the synthetic reference stays fixed. Same nominal wavelength and setup are assumed.','A persistent change supports investigation. No failure probability or failure date is justified by this synthetic sequence.'],end:['Unexpected early end','The signal drops to the modeled noise floor at 3.5 km, before the expected 4.7 km end.','Check range, upstream loss, baseline and opposite direction. A break is possible even without a strong reflection.']};
function renderLab(){const info=scenarioInfo[state.scenario];$('#main').innerHTML=`<div class="eyebrow">OTDR TRACE LAB</div><h1>See how the relationships work.</h1><p class="muted">Change one condition. Compare the evidence. Explain the next check.</p>${notice()}<div class="controls"><label>Practice scenario<select id="scenario">${Object.entries(scenarioInfo).map(([k,v])=>`<option value="${k}">${v[0]}</option>`).join('')}</select></label><label>Trace display<select id="wave"><option value="both">Compare both</option><option value="1310">${state.scenario==='gainer'?'A → B only':state.scenario==='trend'?'Baseline only':'1310 nm only'}</option><option value="1550">${state.scenario==='gainer'?'B → A only':state.scenario==='trend'?'Follow-up only':'1550 nm only'}</option></select></label></div><div class="lab-layout"><div><div class="chart" id="trace">${chart(state.scenario,state.wave,state.pulse,state.day)}</div><div class="panel" id="adjust">${state.scenario==='pulse'?`<label for="pulse">Illustrative pulse width: <b id="pulseValue">${state.pulse} ns</b></label><input id="pulse" type="range" min="10" max="200" step="10" value="${state.pulse}"><p class="meta">Watch the two nearby events blend. This is a qualitative demonstration, not a calibrated instrument model.</p>`:state.scenario==='trend'?`<label for="day">Follow-up: <b id="dayValue">day ${state.day}</b></label><input id="day" type="range" min="0" max="10" value="${state.day}"><p id="trendValue">Event loss: ${(0.4+state.day*.22).toFixed(2)} dB; baseline 0.40 dB. Synthetic daily observations.</p>`:'<b>Look near 2.5 km.</b><p>Compare a step in the backscatter with a reflective peak. Loss and reflection describe different properties.</p>'}</div></div><div class="panel" style="margin-top:0"><div class="eyebrow">READ THE EVIDENCE</div><h2 style="margin-top:12px">${info[0]}</h2><p>${info[1]}</p><h3>What to verify</h3><p>${info[2]}</p><span class="badge">No pass/fail threshold applied</span></div></div><section class="panel"><h2>Make the next decision</h2><p>Does this display alone establish an AT&T pass/fail result?</p><div class="answers"><button class="answer" id="yes">Yes, the shape is enough.</button><button class="answer" id="no">No. Verify setup and apply the current approved criteria.</button></div><div id="labFeedback" aria-live="polite"></div></section>${footer()}`;$('#scenario').value=state.scenario;$('#wave').value=state.wave;$('#scenario').onchange=e=>{state.scenario=e.target.value;state.wave='both';renderLab()};$('#wave').onchange=e=>{state.wave=e.target.value;$('#trace').innerHTML=chart(state.scenario,state.wave,state.pulse,state.day)};if($('#pulse'))$('#pulse').oninput=e=>{state.pulse=+e.target.value;$('#pulseValue').textContent=state.pulse+' ns';$('#trace').innerHTML=chart(state.scenario,state.wave,state.pulse,state.day)};if($('#day'))$('#day').oninput=e=>{state.day=+e.target.value;$('#dayValue').textContent='day '+state.day;$('#trendValue').textContent=`Event loss: ${(0.4+state.day*.22).toFixed(2)} dB; baseline 0.40 dB. Synthetic daily observations.`;$('#trace').innerHTML=chart(state.scenario,state.wave,state.pulse,state.day)};$('#yes').onclick=()=>$('#labFeedback').innerHTML='<div class="feedback retry">Shape helps interpret an event, but cannot establish acceptance without valid measurements and governing criteria.</div>';$('#no').onclick=()=>$('#labFeedback').innerHTML='<div class="feedback">Correct. Confirm the measurement, then apply the authorized procedure and limits. This lab has neither live data nor AT&T acceptance rules.</div>'}
function renderAids(){$('#main').innerHTML=`<div class="eyebrow">FIELD REFERENCE</div><h1>A quick check before the next step.</h1><p class="muted">General learning reminders. Current approved procedures govern field work.</p>${notice()}<div class="panel"><h2>Four questions to carry with you</h2>${[['Can I trust this measurement?','Verify asset and direction, wavelength, pulse, range, averaging, refractive index, leads and sufficient signal. Preserve raw results.'],['What is directly observable?','Describe location, reflection, loss, slope or change. Keep the observation separate from the suspected physical cause.'],['What would confirm my interpretation?','Compare directions, wavelengths and baseline as permitted. Check artifacts and dead zones before assigning a defect.'],['What authorizes the next action?','Use the current applicable procedure and acceptance criteria. Stop and escalate when required or when evidence remains insufficient.']].map(([h,p])=>`<details><summary>${h}</summary><p>${p}</p></details>`).join('')}</div><div class="panel"><h2>Plain-language terms</h2>${[['Event loss','The change in estimated transmitted power across an event, reported in dB. Keep signed directional values when averaging a matched event.'],['Reflectance','The ratio of reflected power to incident power, usually expressed as a negative dB value. −35 dB is more reflective than −50 dB. Trace peak height is not itself a calibrated reflectance reading.'],['Attenuation','Loss distributed over distance, often expressed in dB/km. A slope is different from a discrete event step.'],['Dead zone','A region near a strong event where another event cannot be resolved or its loss cannot be measured reliably. Detection and loss-measurement dead zones differ.'],['OTDR versus loss testing','OTDR locates and characterizes events using returned light. A light source and power meter/OLTS measure end-to-end insertion loss. Use the required test method; do not treat the tools as interchangeable.'],['Optical safety','Do not look into optical ports or fiber ends. Use only authorized inspection equipment and the applicable safety and live-fiber testing procedure.'],['Anomaly versus prediction','An anomaly is a difference from an expected pattern. A prediction needs a defined future outcome and evidence of reliable warning on independent data.']].map(([h,p])=>`<details><summary>${h}</summary><p>${p}</p></details>`).join('')}</div><div class="panel"><h2>Practice data on this phone</h2><p>Progress is stored only in this browser. There is no account sync, technician ranking or employer qualification record.</p><button class="secondary" id="reset">Clear my practice progress</button><p id="resetResult" aria-live="polite"></p></div>${footer()}`;$('#reset').onclick=()=>{state.done=[];save();$('#resetResult').textContent='Practice progress cleared on this device.'}}
function renderDesign(){$('#main').innerHTML=`<div class="eyebrow">SYSTEM BLUEPRINT</div><h1>From trace sets to shared expertise.</h1><p class="muted">A concrete implementation plan for engineering, operations and training leads.</p>${notice()}<div class="panel"><h2>Two connected workflows</h2><div class="flow"><span>Collect</span><i>→</i><span>Validate</span><i>→</i><span>Compare</span><i>→</i><span>Review</span><i>→</i><span>Teach</span></div><p style="margin-top:20px">Instrument collection and predictive analytics are proposed production components. This app implements the synthetic learning experience; it does not connect to instruments, ingest network files or predict live failures.</p><a class="secondary" style="display:inline-block;text-decoration:none" href="./blueprint.html">Read the full system & training design →</a></div><div class="cards"><div class="card"><div class="number">ENGINEERING</div><h3>Comparable trace sets</h3><p>Keep raw traces, settings and asset identity together. Quarantine incomplete measurements before event analysis.</p></div><div class="card"><div class="number">RELIABILITY</div><h3>Evidence before prediction</h3><p>Start with rules and trends. Validate warning horizons, false alerts and lead time against confirmed incidents.</p></div><div class="card"><div class="number">KNOWLEDGE TRANSFER</div><h3>One case, one decision</h3><p>Capture a short expert explanation, review the governing procedure, then turn it into a 3–5 minute lesson.</p></div></div><div class="panel"><h2>SME case capture template</h2><p>Use an approved internal system for actual cases. Do not enter network or personnel data into this prototype.</p><ol><li>Describe the de-identified situation and comparable trace settings.</li><li>Record the observation and alternative explanations.</li><li>Explain the confirmation test and approved next action.</li><li>Attach the governing source, version and scope.</li><li>Obtain technical and policy review before publishing.</li></ol></div>${footer()}`}
let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#installState').textContent='Your browser supports installation. Select “Install on this device” below.';let b=document.createElement('button');b.className='primary';b.textContent='Install on this device';b.onclick=async()=>{await installPrompt.prompt();installPrompt=null;b.remove()};$('#installState').after(b)});$('#install').onclick=()=>$('#phone').showModal();$('.close').onclick=()=>$('#phone').close();
if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{$('#offlineStatus').textContent='Learning files ready for offline use'}).catch(()=>{$('#offlineStatus').textContent='Online mode · offline setup unavailable'})}else $('#offlineStatus').textContent='Online mode';go('learn');

